	private static java.util.Map<String, String> english;

	/** The English name of a Japanese menu or item name (half-width kana as full-width; "..." as "…"), or null */
	static synchronized String english(String japanese) {
		if (japanese == null) return null;
		if (english == null) {
			english = new java.util.HashMap<>();
			for (int i = 0; i + 1 < PAIRS.length; i += 2) english.putIfAbsent(key(PAIRS[i + 1]), PAIRS[i]);
		}
		return english.get(key(japanese));
	}
	private static String key(String s) { return Platform.get().normalize(s.trim().replace("...", "…"), UnicodeNorm.Form.NFKC).toLowerCase(java.util.Locale.ROOT); }
